import java.nio.file.*;
import java.util.*;
public class StowRun {
  public static int run(String reel) throws Exception {
    Gear g = Gear.load("/app/gearpit/live.gear");
    byte[] src = Files.readAllBytes(Paths.get(reel));
    String name = Paths.get(reel).getFileName().toString();
    Path marks = Paths.get("/app/urnbay/marks");
    Path flag = marks.resolve(name + ".flag");
    Path mk = marks.resolve(name + ".m");
    boolean prior = Files.exists(flag);
    Map<String,String> idx = Idx.load();

    // A known reel may have been cut with an older gear.  Reuse its recorded
    // boundaries, but only after proving that the manifest still spells the
    // exact bytes supplied by the caller.
    List<String> keys = new ArrayList<>();
    List<byte[]> parts = new ArrayList<>();
    if (Files.exists(mk)) {
      boolean complete = true;
      for (String line : Files.readAllLines(mk)) {
        String key = line.trim();
        if (key.isEmpty()) continue;
        String rel = idx.get(key);
        if (rel == null) { complete = false; break; }
        try {
          parts.add(Idx.blob(rel));
          keys.add(key);
        } catch (java.io.IOException e) {
          complete = false;
          break;
        }
      }
      if (!complete || !same(src, parts)) {
        keys.clear();
        parts.clear();
      }
    }

    long stored = 0;
    long reused = 0;
    if (!parts.isEmpty() || src.length == 0 && Files.exists(mk)) {
      reused = src.length;
    } else {
      parts = Slice.cut(src, g.mask, g.min, g.max);
      Path hot = Paths.get("/app/urnbay/hot");
      Files.createDirectories(hot);
      for (byte[] part : parts) {
        String key = Seal.hex(part, g.fp);
        String pay = Seal.pay(part);
        String hit = idx.containsKey(key) ? key : (idx.containsKey(pay) ? pay : null);
        if (hit != null) {
          reused += part.length;
          keys.add(hit);
        } else {
          stored += part.length;
          String rel = "hot/" + key + ".blob";
          Files.write(hot.resolve(key + ".blob"), part);
          Idx.put(key, rel);
          idx.put(key, rel);
          keys.add(key);
        }
      }
    }

    Files.createDirectories(marks);
    StringBuilder manifest = new StringBuilder();
    for (String key : keys) manifest.append(key).append('\n');
    Files.writeString(mk, manifest.toString());
    double reuse = src.length == 0 ? 1.0 : reused / (double)src.length;
    double mean = parts.isEmpty() ? 0.0 : src.length / (double)parts.size();
    String json = "{\n"
      + "  \"reel\": \"" + name + "\",\n"
      + "  \"bytes_in\": \"" + src.length + "\",\n"
      + "  \"bytes_stored\": \"" + stored + "\",\n"
      + "  \"reuse_frac\": \"" + String.format(Locale.US, "%.4f", reuse) + "\",\n"
      + "  \"mean_piece\": \"" + String.format(Locale.US, "%.4f", mean) + "\",\n"
      + "  \"piece_count\": \"" + parts.size() + "\"\n"
      + "}\n";
    Files.writeString(Paths.get("/app/urnbay/tally.json"), json);
    Files.writeString(Paths.get("/app/urnbay/last.json"), json);
    Floor.ok(reuse);
    if (prior && stored == src.length && src.length > 0) return 1;
    Files.writeString(flag, "1\n");
    return 0;
  }

  static boolean same(byte[] src, List<byte[]> parts) {
    int offset = 0;
    for (byte[] part : parts) {
      if (offset + part.length > src.length) return false;
      for (int i = 0; i < part.length; i++)
        if (src[offset + i] != part[i]) return false;
      offset += part.length;
    }
    return offset == src.length;
  }
}
